/bin/zsh -c "python3 - <<'PY'
import json
fees=json.load(open('inputs/fees.json'))
print('fee rows',len(fees), 'IDs',min(x['ID'] for x in fees),max(x['ID'] for x in fees))
for f in fees:
 if f['ID']==384 or (f['card_scheme']=='GlobalCard' and (f['is_credit'] is True or f['is_credit'] is None)):
  if f['ID']==384 or f['account_type'] or f['merchant_category_code']:
   print(f)
PY"

