# capture delay mapping from merchant profile to fee categories
def capmatch(rule,merchant_cap):
 if rule is None:return True
 if merchant_cap=='immediate' or merchant_cap=='manual':return rule==merchant_cap
 d=int(merchant_cap)
 if rule=='<3':return d<3
 if rule=='3-5':return 3<=d<=5
 if rule=='>5':return d>5
 return False

def merchant_static(r, cap, acct, mcc):
 return (not r['account_type'] or acct in r['account_type']) and capmatch(r['capture_delay'],cap) and (not r['merchant_category_code'] or mcc in r['merchant_category_code'])
# all with monthly Jan/Mar stats
def merchant_month(r,cap,acct,mcc,vol,fraud):
 if not merchant_static(r,cap,acct,mcc): return False
 if r['monthly_volume'] is not None and r['monthly_volume']"'!=vol:return False
 if r['"'monthly_fraud_level'] is not None and r['monthly_fraud_level']"'!=fraud:return False
 return True

def txmatch(r,scheme,cred,aci,dom):
 return r['"'card_scheme']==scheme and (r['is_credit'] is None or r['is_credit']==cred) and (not r['aci'] or aci in r['aci']) and (r['intracountry'] is None or bool(int(r['intracountry']))==dom)
# collect belles transaction configs day 10 and monthly all
configs={'day10':set(),'jan':set(),'mar':set()}
