for label,cfgs,vol,fraud in [('day10',configs['day10'],'100k-1m','>8.3%'),('jan',configs['jan'],'100k-1m','>8.3%'),('mar',configs['mar'],'100k-1m','>8.3%')]:
 ids=set(); rows=[]
 for r in fees:
  if merchant_month(r,'1','R',5942,vol,fraud):
   rows.append(r)
   if any(txmatch(r,*c) for c in cfgs):ids.add(r['ID'])
 print('\\n',label,'configs',len(cfgs),'merchant-month base rules',len(rows),'union ids',len(ids))
 print('base ids',','.join(str(x['ID']) for x in rows))
 print('union ids',','.join(map(str,sorted(ids))))
 # Count matching configs per ID and distinguish no transaction dims
 bycols=collections.Counter()
 for r in rows:
  if r['ID'] in ids:
   bycols[(bool(r['aci']),r['is_credit'],r['intracountry'])]+=1
 print('footprint',bycols)
# merchant-only if ignore txn dims count
rows=[r for r in fees if merchant_month(r,'1','R',5942,'100k-1m','>8.3%')]
print('\\nmerchant-only count',len(rows))
